package app.dayflow;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.widget.*;
import org.json.*;
import java.time.*;
import java.util.*;

/** Device-local running timer, one final synced note; no second-by-second background loop. */
public final class FocusTimer extends BroadcastReceiver {
 private static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("focus",0);}
 private static PendingIntent alarm(Context c){return PendingIntent.getBroadcast(c,0,new Intent(c,FocusTimer.class).setAction("app.dayflow.FOCUS_FINISH"),PendingIntent.FLAG_IMMUTABLE);}
 static void entry(MainActivity a,LinearLayout page,JSONObject r){if(java.util.Arrays.asList("task","project","event","course").contains(r.optString("kind")))page.addView(Ui.button(a,"开始专注计时",false,()->show(a,r)));}
 static void show(MainActivity a,JSONObject record){LinearLayout page=a.fullPage("专注计时",a::home);page.addView(Ui.text(a,record==null?"专注":record.optString("title"),24,true));com.google.android.material.textfield.TextInputEditText length=Ui.field(a,page,"专注分钟（1–240）","25",false);length.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);TextView clock=Ui.text(a,"",40,true);page.addView(clock);Handler handler=new Handler(Looper.getMainLooper());Runnable tick=new Runnable(){public void run(){if(!clock.isAttachedToWindow())return;try{JSONObject run=new JSONObject(prefs(a).getString("active","{}"));long left=Math.max(0,run.optLong("end")-System.currentTimeMillis());clock.setText(run.has("id")?String.format(Locale.ROOT,"%02d:%02d",left/60000,left/1000%60):"准备开始");if(run.has("id")&&left==0)finish(a);}catch(Exception ignored){}handler.postDelayed(this,1000);}};clock.post(tick);
  page.addView(Ui.button(a,"开始",true,()->{try{if(!prefs(a).getString("active","").isEmpty())throw new Exception("已有专注计时，请先结束或取消");int minutes=Integer.parseInt(length.getText().toString());if(minutes<1||minutes>240)throw new Exception("分钟需在1–240之间");JSONObject run=new JSONObject().put("id",UUID.randomUUID().toString()).put("title",record==null?"专注":record.optString("title")).put("parent",record==null?"":record.optString("id")).put("start",System.currentTimeMillis()).put("end",System.currentTimeMillis()+minutes*60000L);prefs(a).edit().putString("active",run.toString()).commit();restore(a);a.notificationPermission();a.message("专注已开始，切到后台由系统定时提醒");}catch(Exception e){a.message(e.getMessage());}}));page.addView(Ui.button(a,"提前结束并保存投入时间",false,()->{finish(a);a.message("已保存专注记录");show(a,record);}));page.addView(Ui.button(a,"取消本次计时",false,()->{prefs(a).edit().remove("active").apply();((AlarmManager)a.getSystemService(Context.ALARM_SERVICE)).cancel(alarm(a));a.message("已取消，不生成记录");}));page.addView(Ui.help(a,"专注逻辑参考Super Productivity。后台不逐秒唤醒，结束后生成独立笔记并同步。提醒受通知权限与系统调度影响。"));}
 static void restore(Context c){try{JSONObject run=new JSONObject(prefs(c).getString("active","{}"));if(!run.has("id"))return;if(run.getLong("end")<=System.currentTimeMillis()){finish(c);return;}AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);try{if(AlarmSound.exact(c))am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,run.getLong("end"),alarm(c));else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,run.getLong("end"),alarm(c));}catch(SecurityException e){am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,run.getLong("end"),alarm(c));}}catch(Exception ignored){}}
 private static synchronized void finish(Context c){try{JSONObject run=new JSONObject(prefs(c).getString("active","{}"));if(!run.has("id"))return;long seconds=Math.max(0,(Math.min(System.currentTimeMillis(),run.getLong("end"))-run.getLong("start"))/1000);String id=UUID.nameUUIDFromBytes(("focus:"+run.getString("id")).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();if(Data.get(c).find(id)==null){JSONObject r=Data.make("note","专注 · "+run.optString("title")).put("id",id).put("focus_for",run.optString("parent")).put("focus_seconds",seconds).put("content","投入时间："+seconds/60+"分"+seconds%60+"秒\n结束于："+LocalDateTime.now()).put("content_format","markdown");Data.get(c).save(r);}prefs(c).edit().remove("active").commit();((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).cancel(alarm(c));AgendaWidget.refresh(c);}catch(Exception ignored){}}
 public void onReceive(Context c,Intent intent){PendingResult pending=goAsync();new Thread(()->{try{if(prefs(c).getString("active","").isEmpty())return;JSONObject run=new JSONObject(prefs(c).getString("active","{}"));if(run.optLong("end")>System.currentTimeMillis()){restore(c);return;}finish(c);NotificationManager nm=c.getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("focus_done","专注完成",NotificationManager.IMPORTANCE_HIGH));PendingIntent open=PendingIntent.getActivity(c,0,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE);try{nm.notify(712,new Notification.Builder(c,"focus_done").setSmallIcon(R.drawable.ic_notification).setContentTitle("专注完成").setContentText("本次投入已保存到笔记").setContentIntent(open).setAutoCancel(true).build());}catch(SecurityException ignored){}}catch(Exception ignored){}finally{pending.finish();}},"focus-finish").start();}
}
